/**
 * Serviço WhatsApp (Módulo 8: Comunicação Externa & Envio).
 * Envia links de propostas e confirmações via WhatsApp (WhatsApp Business API
 * ou links wa.me gratuitos). Solução gratuita: links diretos wa.me.
 */

export type SendWhatsAppParams = {
  telefone: string;
  mensagem: string;
};

export type WhatsAppResult = { sucesso: boolean; url?: string; erro?: string };

export class WhatsAppService {
  async enviar(params: SendWhatsAppParams): Promise<WhatsAppResult> {
    try {
      const telefoneLimpo = params.telefone.replace(/\D/g, '');
      const url = `https://wa.me/${telefoneLimpo}?text=${encodeURIComponent(params.mensagem)}`;
      console.log('[WhatsAppService] Link gerado:', url);
      return { sucesso: true, url };
    } catch (e) {
      return {
        sucesso: false,
        erro: e instanceof Error ? e.message : 'Erro ao gerar link WhatsApp',
      };
    }
  }

  async enviarProposta(
    telefone: string,
    orcamentoNumero: string,
    linkPublico: string,
  ): Promise<WhatsAppResult> {
    return this.enviar({
      telefone,
      mensagem: `Olá! Sua proposta ${orcamentoNumero} está pronta para revisão:\n${linkPublico}\n\nAtt., CRM Super`,
    });
  }

  async enviarConfirmacaoAgendamento(
    telefone: string,
    cliente: string,
    data: string,
    tipo: 'visita' | 'medicao' | 'instalacao',
  ): Promise<WhatsAppResult> {
    const tipoLabel = {
      visita: 'Visita',
      medicao: 'Medição',
      instalacao: 'Instalação',
    }[tipo];
    return this.enviar({
      telefone,
      mensagem: `Olá ${cliente}, seu agendamento de ${tipoLabel} foi confirmado para ${data}.\n\nAtt., CRM Super`,
    });
  }
}

export const whatsAppService = new WhatsAppService();
